            EditorGUILayout.LabelField("Initialized", isInit ? "Yes" : "No");

            if (isInit)
            {
                EditorGUILayout.LabelField("Scroll Height", container.ScrollHeight.ToString("F1"));
                EditorGUILayout.LabelField("Scroll Position", container.ScrollPosition.ToString("F1"));
                EditorGUILayout.LabelField("Max Scroll Position", container.MaxScrollPosition.ToString("F1"));
            }

            EditorGUILayout.Space(5);

            using (new EditorGUI.DisabledScope(!isInit))
            {
                EditorGUILayout.BeginHorizontal();
                if (GUILayout.Button("Clear", GUILayout.Height(30))) container.Clear();
                if (GUILayout.Button("Refresh", GUILayout.Height(30))) container.Refresh();
                if (GUILayout.Button("Rebuild", GUILayout.Height(30))) container.Rebuild();
                EditorGUILayout.EndHorizontal();
            }

            if (isInit) Repaint();
